    def man(x1, y1, x2, y2):
        dx = x1 - x2
        if dx < 0: dx = -dx
        dy = y1 - y2
        if dy < 0: dy = -dy
        return dx + dy

    def nearest_dist(x, y, pts):
        if not pts:
            return 10**9
        md = 10**9
        for rx, ry in pts:
            d = man(x, y, rx, ry)
            if d < md:
                md = d
        return md

    def count_near(x, y, pts, thr=2):
        c = 0
        for rx, ry in pts:
            if man(x, y, rx, ry) <= thr:
                c += 1
        return c

    best_score = None
    best_move = [0, 0]

    any_res = bool(resources)
    for dx, dy in deltas:
        nx, ny = sx + dx, sy + dy
        if blocked(nx, ny):
            continue

        if any_res:
